// table PaddedRow — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (SPEC-TABLES.md)
struct PaddedRow {
    uint8_t tag = 0;
    double value = 0.0;
    bool flag = false;
    uint32_t id = 0;
    char label[15 + 1] = {}; // string(15): max length, used length beside it
    int32_t label_length = 0;
    uint16_t slots[4] = {};
    TableKeyed<uint8_t, Team> teams; // [Team]: one slot per named variant, keyed by the value
    int32_t counter = 0;
    bool counter_present = false; // ?int32: absent until set
};

// table PaddedFrame — TABLE-wire storage: relocatable, bounded, defaults in the
// member initializers (SPEC-TABLES.md)
struct PaddedFrame {
    uint8_t marker = 0;
    uint64_t stamp = 0;
    PaddedRow rows[64]; // used count beside it; count in [0, 64]
    int32_t rows_count = 0;
    uint8_t blob[12] = {}; // bytes(12): fixed buffer, used length beside it
    int32_t blob_length = 0;
};

// Team on the TABLE wire: a value rides as the u16 hash of its VARIANT
// NAME, so a variant may be added anywhere, removed, or reordered and old
// data still reads (SPEC-TABLES.md §5). None is the one reserved id, 0.
#ifndef BLOCKDEMO_SCHEMA_TABLE_ENUM_TEAM
#define BLOCKDEMO_SCHEMA_TABLE_ENUM_TEAM
inline bool TableEnumId( Team value, uint16_t & id )
{
    switch ( value )
    {
        case Team::None: id = 0; return true;
        case Team::Red: id = 0xbb03; return true;
        case Team::Blue: id = 0xf630; return true;
        case Team::Green: id = 0x6e0f; return true;
        case Team::Gold: id = 0xda27; return true;
        default: return false; // no variant names this value: no wire identity
    }
}
inline bool TableEnumValue( uint16_t id, Team & out )
{
    switch ( id )
    {
        case 0: out = Team::None; return true;
        case 0xbb03: out = Team::Red; return true;
        case 0xf630: out = Team::Blue; return true;
        case 0x6e0f: out = Team::Green; return true;
        case 0xda27: out = Team::Gold; return true;
        default: return false; // an id this build cannot name
    }
}
#endif // BLOCKDEMO_SCHEMA_TABLE_ENUM_TEAM

// ---- prefill: the declared defaults, in place (SPEC-TABLES.md) ----

inline void PaddedRowReset( PaddedRow & value );
inline void PaddedFrameReset( PaddedFrame & value );

inline void PaddedRowReset( PaddedRow & value )
{
    value.tag = 0;
    value.value = 0.0;
    value.flag = false;
    value.id = 0;
    memset( value.label, 0, sizeof( value.label ) );
    value.label_length = 0;
    memset( value.slots, 0, sizeof( value.slots ) );
    memset( value.teams.slots, 0, sizeof( value.teams.slots ) );
    value.counter = 0;
    value.counter_present = false;
}

inline void PaddedFrameReset( PaddedFrame & value )
{
    value.marker = 0;
    value.stamp = 0;
    PaddedRowReset( value.rows[0] );
    for ( int32_t i = 1; i < 64; i++ ) { value.rows[i] = value.rows[0]; }
    value.rows_count = 0;
    memset( value.blob, 0, sizeof( value.blob ) );
    value.blob_length = 0;
}

// ---- codecs: measure/save/load per closure member ----

inline int64_t PaddedRowMeasure( const PaddedRow & value );
inline bool PaddedRowSaveBody( TableWriter & w, const PaddedRow & value );
inline bool PaddedRowLoadBody( TableReader & r, PaddedRow & value );
inline int64_t PaddedFrameMeasure( const PaddedFrame & value );
inline bool PaddedFrameSaveBody( TableWriter & w, const PaddedFrame & value );
inline bool PaddedFrameLoadBody( TableReader & r, PaddedFrame & value );

inline int64_t PaddedRowMeasure( const PaddedRow & value )
{
    int64_t bytes = 2; // terminator
    if ( value.tag != 0 ) { bytes += 3 + 1; } // tag
    if ( value.value != 0.0 ) { bytes += 3 + 8; } // value
    if ( value.flag != false ) { bytes += 3 + 1; } // flag
    if ( value.id != 0 ) { bytes += 3 + 4; } // id
    if ( value.label_length < 0 || value.label_length > 15 ) { return -1; } // storage invariant
    if ( value.label_length > 0 ) { bytes += 3 + 4 + value.label_length; } // label
    {
        bool all_default_slots = true;
        for ( int32_t i = 0; i < 4; i++ ) { if ( value.slots[i] != 0 ) { all_default_slots = false; break; } }
        if ( !all_default_slots )
        {
            bytes += 3 + 4 + 5 + 8; // slots
        }
    }
    {
        int64_t pairs_teams = 0, body_teams = 0;
        for ( int32_t i = 0; i < 4; i++ ) // [Team]: every stored slot is a named variant's
        {
            if ( value.teams.slots[i] == 0 ) { continue; } // a default slot elides
            uint16_t key_id = 0;
            if ( !TableEnumId( Team( i + 1 ), key_id ) ) { return -1; } // i is the STORAGE index; the key it holds is i + 1
            pairs_teams++; body_teams += 2 + 4 + 1; // key, length, element
        }
        if ( pairs_teams > 0 ) { bytes += 3 + 4 + 5 + body_teams; } // teams
    }
    if ( value.counter_present ) // ?int32: presence decides, not content
    {
        bytes += 3 + 4; // counter
    }
    return bytes;
}

inline bool PaddedRowSaveBody( TableWriter & w, const PaddedRow & value )
{
    if ( value.tag != 0 )
    {
        w.put16( 0xbc64 ); w.put8( 6 ); // tag
        w.put8( uint8_t( value.tag ) );
    }
    if ( value.value != 0.0 )
    {
        w.put16( 0x9194 ); w.put8( 11 ); // value
        w.put64( table_double_to_bits( value.value ) );
    }
    if ( value.flag != false )
    {
        w.put16( 0x153d ); w.put8( 1 ); // flag
        w.put8( value.flag ? 1 : 0 );
    }
    if ( value.id != 0 )
    {
        w.put16( 0x5dd8 ); w.put8( 8 ); // id
        w.put32( uint32_t( value.id ) );
    }
    if ( value.label_length < 0 || value.label_length > 15 ) { return false; } // storage invariant
    if ( value.label_length > 0 )
    {
        w.put16( 0xe16a ); w.put8( 12 ); // label
        w.put32( uint32_t( value.label_length ) );
        w.raw( value.label, value.label_length );
    }
    {
        bool all_default_slots = true;
        for ( int32_t i = 0; i < 4; i++ ) { if ( value.slots[i] != 0 ) { all_default_slots = false; break; } }
        if ( !all_default_slots )
        {
            w.put16( 0xf4d8 ); w.put8( 14 ); // slots (fixed [4])
            int64_t len_at_slots = w.offset; w.put32( 0 );
            w.put8( 7 ); w.put32( 4 );
            for ( int32_t i = 0; i < 4; i++ )
            {
                w.put16( uint16_t( value.slots[i] ) );
            }
            w.patch32( len_at_slots, uint32_t( w.offset - len_at_slots - 4 ) );
        }
    }
    {
        uint32_t pairs_teams = 0;
        for ( int32_t i = 0; i < 4; i++ ) // [Team]: every stored slot is a named variant's
        {
            if ( value.teams.slots[i] == 0 ) { continue; } // a default slot elides
            uint16_t key_id = 0;
            if ( !TableEnumId( Team( i + 1 ), key_id ) ) { return false; } // i is the STORAGE index; the key it holds is i + 1
            pairs_teams++;
        }
        if ( pairs_teams > 0 )
        {
            // KIND 16, not 14: a keyed body and a positional one are
            // incompatible, so a reader of the other kind must see a kind
            // mismatch and skip, never misdecode (SPEC-TABLES.md §3.2)
            w.put16( 0x9ae1 ); w.put8( 16 ); // teams (keyed by Team)
            int64_t len_at_teams = w.offset; w.put32( 0 );
            w.put8( 6 ); w.put32( pairs_teams );
            // ASCENDING BY VARIANT ORDINAL, which is slot order — this
            // writer's choice, and a reader must not rely on it: every
            // slot is found by its key (SPEC-TABLES.md §3.2)
            for ( int32_t i = 0; i < 4; i++ )
            {
                if ( value.teams.slots[i] == 0 ) { continue; } // a default slot elides
                uint16_t key_id = 0;
                if ( !TableEnumId( Team( i + 1 ), key_id ) ) { return false; } // i is the STORAGE index; the key it holds is i + 1
                w.put16( key_id ); // the slot's VARIANT id, not its position
                int64_t elem_len_at_teams = w.offset; w.put32( 0 );
                w.put8( uint8_t( value.teams.slots[i] ) );
                w.patch32( elem_len_at_teams, uint32_t( w.offset - elem_len_at_teams - 4 ) );
            }
            w.patch32( len_at_teams, uint32_t( w.offset - len_at_teams - 4 ) );
        }
    }
    if ( value.counter_present ) // ?int32
    {
        w.put16( 0x428f ); w.put8( 4 ); // counter
        w.put32( uint32_t( value.counter ) );
    }
    w.put16( 0 ); // terminator
    return !w.overflow;
}

inline int64_t PaddedRowSave( const PaddedRow & value, uint8_t * buffer, int64_t capacity )
{
    TableWriter w( buffer, capacity );
    if ( !PaddedRowSaveBody( w, value ) ) { return -1; }
    return w.offset; // == PaddedRowMeasure( value )
}

inline bool PaddedRowLoadBody( TableReader & r, PaddedRow & value )
{
    PaddedRowReset( value ); // prefill declared defaults in place, then overlay
    for ( ;; )
    {
        if ( !r.has( 2 ) ) { r.report->malformed = true; return false; }
        uint16_t field_id = r.get16();
        if ( field_id == 0 ) return true;
        if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
        uint8_t kind = r.get8();
        switch ( field_id )
        {
            case 0xbc64: // tag
            {
                if ( kind != 6 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
                uint8_t decoded_v = uint8_t( r.get8( ) );
                value.tag = decoded_v;
                break;
            }
            case 0x9194: // value
            {
                if ( kind != 11 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 8 ) ) { r.report->malformed = true; return false; }
                value.value = table_bits_to_double( r.get64() );
                break;
            }
            case 0x153d: // flag
            {
                if ( kind != 1 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
                value.flag = r.get8() != 0;
                break;
            }
            case 0x5dd8: // id
            {
                if ( kind != 8 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t decoded_v = uint32_t( r.get32( ) );
                value.id = decoded_v;
                break;
            }
            case 0xe16a: // label
            {
                if ( kind != 12 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t len = r.get32();
                if ( !r.has( len ) ) { r.report->malformed = true; return false; }
                uint32_t keep = len;
                if ( keep > 15 ) { keep = 15; r.report->clamped++; }
                memcpy( value.label, r.buffer + r.offset, keep );
                value.label[keep] = 0;
                value.label_length = (int32_t) keep;
                r.offset += len;
                break;
            }
            case 0xf4d8: // slots
            {
                if ( kind != 14 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t body_len = r.get32();
                if ( !r.has( body_len ) ) { r.report->malformed = true; return false; }
                int64_t body_end = r.offset + body_len;
                if ( body_len >= 5 )
                {
                    uint8_t elem_kind = r.get8();
                    uint32_t count = r.get32();
                    if ( elem_kind != 7 ) { r.report->kind_mismatch++; r.offset = body_end; break; }
                    uint32_t keep = count;
                    if ( keep > 4 ) { keep = 4; r.report->clamped++; }
                    // elements are BOUNDED by the field body: a count the length
                    // cannot cover keeps the decoded prefix, flags malformed, and
                    // the parent continues at the next field — following fields'
                    // bytes are never fabricated into elements
                    TableReader sub( r.buffer + r.offset, body_end - r.offset, r.report );
                    for ( uint32_t i = 0; i < keep; i++ )
                    {
                        if ( !sub.has( 2 ) ) { r.report->malformed = true; break; }
                        uint16_t decoded_v = uint16_t( sub.get16( ) );
                        value.slots[i] = decoded_v;
                    }
                }
                r.offset = body_end; // excess elements and slack skip via the length
                break;
            }
            case 0x9ae1: // teams
            {
                if ( kind != 16 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t body_len = r.get32();
                if ( !r.has( body_len ) ) { r.report->malformed = true; return false; }
                int64_t body_end = r.offset + body_len;
                if ( body_len >= 5 )
                {
                    uint8_t elem_kind = r.get8();
                    uint32_t count = r.get32();
                    if ( elem_kind != 6 ) { r.report->kind_mismatch++; r.offset = body_end; break; }
                    TableReader sub( r.buffer + r.offset, body_end - r.offset, r.report );
                    for ( uint32_t i = 0; i < count; i++ )
                    {
                        if ( !sub.has( 2 ) ) { r.report->malformed = true; break; }
                        uint16_t key = sub.get16();
                        if ( !sub.has( 4 ) ) { r.report->malformed = true; break; }
                        uint32_t elem_len = sub.get32();
                        if ( !sub.has( elem_len ) ) { r.report->malformed = true; break; }
                        if ( key == 0 )
                        {
                            // None is the NULL KEY: 0 is the reserved id no declared
                            // name can fold to, so a body carrying one is DAMAGED, not
                            // merely foreign. Framing damage stops this body, keeps what
                            // it decoded, and the parent reads on past the length
                            // (SPEC-TABLES.md §3.2, §4).
                            r.report->malformed = true;
                            break;
                        }
                        Team slot = Team::None;
                        if ( !TableEnumValue( key, slot ) )
                        {
                            r.report->unknown++; // a slot this reader cannot name
                            sub.offset += elem_len;
                            continue;
                        }
                        {
                            TableReader elem( sub.buffer + sub.offset, elem_len, r.report );
                            if ( !elem.has( 1 ) ) { r.report->malformed = true; sub.offset += elem_len; continue; }
                            uint8_t decoded_v = uint8_t( elem.get8( ) );
                            value.teams.slots[int32_t( slot ) - 1] = decoded_v;
                        }
                        sub.offset += elem_len;
                    }
                }
                r.offset = body_end; // unread pairs and slack skip via the length
                break;
            }
            case 0x428f: // counter
            {
                if ( kind != 4 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                int32_t decoded_v = int32_t( r.get32( ) );
                value.counter = decoded_v;
                value.counter_present = true;
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                break;
            }
        }
    }
}

inline bool PaddedRowLoad( PaddedRow & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReader r( buffer, bytes, report != NULL ? report : &ignored );
    return PaddedRowLoadBody( r, value );
}

inline int64_t PaddedFrameMeasure( const PaddedFrame & value )
{
    int64_t bytes = 2; // terminator
    if ( value.marker != 0 ) { bytes += 3 + 1; } // marker
    if ( value.stamp != 0 ) { bytes += 3 + 8; } // stamp
    if ( value.rows_count < 0 || value.rows_count > 64 ) { return -1; } // storage invariant
    if ( value.rows_count > 0 )
    {
        bytes += 3 + 4 + 5; // rows
        for ( int32_t i = 0; i < value.rows_count; i++ )
        {
            int64_t elem_rows = PaddedRowMeasure( value.rows[i] );
            if ( elem_rows < 0 ) { return -1; }
            bytes += 4 + elem_rows;
        }
    }
    if ( value.blob_length < 0 || value.blob_length > 12 ) { return -1; } // storage invariant
    if ( value.blob_length > 0 ) { bytes += 3 + 4 + 5 + value.blob_length; } // blob
    return bytes;
}

inline bool PaddedFrameSaveBody( TableWriter & w, const PaddedFrame & value )
{
    if ( value.marker != 0 )
    {
        w.put16( 0x866f ); w.put8( 6 ); // marker
        w.put8( uint8_t( value.marker ) );
    }
    if ( value.stamp != 0 )
    {
        w.put16( 0x0dc6 ); w.put8( 9 ); // stamp
        w.put64( uint64_t( value.stamp ) );
    }
    if ( value.rows_count < 0 || value.rows_count > 64 ) { return false; } // storage invariant
    if ( value.rows_count > 0 )
    {
        w.put16( 0x99af ); w.put8( 14 ); // rows
        int64_t len_at_rows = w.offset; w.put32( 0 );
        w.put8( 13 ); w.put32( uint32_t( value.rows_count ) );
        for ( int32_t i = 0; i < value.rows_count; i++ )
        {
            {
                int64_t elem_len_at = w.offset; w.put32( 0 );
                if ( !PaddedRowSaveBody( w, value.rows[i] ) ) return false;
                w.patch32( elem_len_at, uint32_t( w.offset - elem_len_at - 4 ) );
            }
        }
        w.patch32( len_at_rows, uint32_t( w.offset - len_at_rows - 4 ) );
    }
    if ( value.blob_length < 0 || value.blob_length > 12 ) { return false; } // storage invariant
    if ( value.blob_length > 0 )
    {
        w.put16( 0xd316 ); w.put8( 14 ); // blob
        w.put32( uint32_t( 5 + value.blob_length ) );
        w.put8( 6 ); w.put32( uint32_t( value.blob_length ) );
        w.raw( value.blob, value.blob_length );
    }
    w.put16( 0 ); // terminator
    return !w.overflow;
}

inline int64_t PaddedFrameSave( const PaddedFrame & value, uint8_t * buffer, int64_t capacity )
{
    TableWriter w( buffer, capacity );
    if ( !PaddedFrameSaveBody( w, value ) ) { return -1; }
    return w.offset; // == PaddedFrameMeasure( value )
}

inline bool PaddedFrameLoadBody( TableReader & r, PaddedFrame & value )
{
    PaddedFrameReset( value ); // prefill declared defaults in place, then overlay
    for ( ;; )
    {
        if ( !r.has( 2 ) ) { r.report->malformed = true; return false; }
        uint16_t field_id = r.get16();
        if ( field_id == 0 ) return true;
        if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
        uint8_t kind = r.get8();
        switch ( field_id )
        {
            case 0x866f: // marker
            {
                if ( kind != 6 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 1 ) ) { r.report->malformed = true; return false; }
                uint8_t decoded_v = uint8_t( r.get8( ) );
                value.marker = decoded_v;
                break;
            }
            case 0x0dc6: // stamp
            {
                if ( kind != 9 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 8 ) ) { r.report->malformed = true; return false; }
                uint64_t decoded_v = uint64_t( r.get64( ) );
                value.stamp = decoded_v;
                break;
            }
            case 0x99af: // rows
            {
                if ( kind != 14 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t body_len = r.get32();
                if ( !r.has( body_len ) ) { r.report->malformed = true; return false; }
                int64_t body_end = r.offset + body_len;
                if ( body_len >= 5 )
                {
                    uint8_t elem_kind = r.get8();
                    uint32_t count = r.get32();
                    if ( elem_kind != 13 ) { r.report->kind_mismatch++; r.offset = body_end; break; }
                    uint32_t keep = count;
                    if ( keep > 64 ) { keep = 64; r.report->clamped++; }
                    // elements are BOUNDED by the field body: a count the length
                    // cannot cover keeps the decoded prefix, flags malformed, and
                    // the parent continues at the next field — following fields'
                    // bytes are never fabricated into elements
                    TableReader sub( r.buffer + r.offset, body_end - r.offset, r.report );
                    uint32_t decoded = 0;
                    for ( uint32_t i = 0; i < keep; i++ )
                    {
                        if ( !sub.has( 4 ) ) { r.report->malformed = true; break; }
                        uint32_t elem_len = sub.get32();
                        if ( !sub.has( elem_len ) ) { r.report->malformed = true; break; }
                        {
                            TableReader elem( sub.buffer + sub.offset, elem_len, r.report );
                            PaddedRowLoadBody( elem, value.rows[i] );
                        }
                        sub.offset += elem_len;
                        decoded = i + 1;
                    }
                    value.rows_count = (int32_t) decoded;
                }
                r.offset = body_end; // excess elements and slack skip via the length
                break;
            }
            case 0xd316: // blob
            {
                if ( kind != 14 )
                {
                    r.report->kind_mismatch++;
                    if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                    break;
                }
                if ( !r.has( 4 ) ) { r.report->malformed = true; return false; }
                uint32_t body_len = r.get32();
                if ( !r.has( body_len ) ) { r.report->malformed = true; return false; }
                int64_t body_end = r.offset + body_len;
                if ( body_len >= 5 )
                {
                    uint8_t elem_kind = r.get8();
                    uint32_t count = r.get32();
                    if ( elem_kind != 6 ) { r.report->kind_mismatch++; r.offset = body_end; break; }
                    uint32_t keep = count;
                    if ( keep > 12 ) { keep = 12; r.report->clamped++; }
                    // elements are BOUNDED by the field body: a count the length
                    // cannot cover keeps the decoded prefix, flags malformed, and
                    // the parent continues at the next field — following fields'
                    // bytes are never fabricated into elements
                    TableReader sub( r.buffer + r.offset, body_end - r.offset, r.report );
                    uint32_t decoded = 0;
                    for ( uint32_t i = 0; i < keep; i++ )
                    {
                        if ( !sub.has( 1 ) ) { r.report->malformed = true; break; }
                        uint8_t decoded_v = uint8_t( sub.get8( ) );
                        value.blob[i] = decoded_v;
                        decoded = i + 1;
                    }
                    value.blob_length = (int32_t) decoded;
                }
                r.offset = body_end; // excess elements and slack skip via the length
                break;
            }
            default:
            {
                r.report->unknown++;
                if ( !r.skip( kind ) ) { r.report->malformed = true; return false; }
                break;
            }
        }
    }
}

inline bool PaddedFrameLoad( PaddedFrame & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReader r( buffer, bytes, report != NULL ? report : &ignored );
    return PaddedFrameLoadBody( r, value );
}

// ---- the cooked form: point at a cook (SPEC-TABLES.md §7) ----

// PaddedRowOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// PaddedRow IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const PaddedRow * PaddedRowOpen( const void * bytes, uint64_t length )
{
    return (const PaddedRow *) TableCookOpen( bytes, length, (uint64_t) sizeof( PaddedRow ), (uint64_t) alignof( PaddedRow ) );
}

// PaddedFrameOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// PaddedFrame IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const PaddedFrame * PaddedFrameOpen( const void * bytes, uint64_t length )
{
    return (const PaddedFrame *) TableCookOpen( bytes, length, (uint64_t) sizeof( PaddedFrame ), (uint64_t) alignof( PaddedFrame ) );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
static_assert( std::is_trivially_copyable<PaddedRow>::value, "PaddedRow must stay relocatable" );
static_assert( std::is_standard_layout<PaddedRow>::value, "PaddedRow must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<PaddedFrame>::value, "PaddedFrame must stay relocatable" );
static_assert( std::is_standard_layout<PaddedFrame>::value, "PaddedFrame must stay standard-layout for offsetof" );

// ---- the cook's layout contract (SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( PaddedRow ) == 64, "PaddedRow's sizeof moved: the build version was taken over 64, so a cook of it would not be this build's file (SPEC-TABLES.md §20.3)" );
static_assert( alignof( PaddedRow ) == 8, "PaddedRow's alignof moved: the build version was taken over 8 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, tag ) == 0, "PaddedRow's field tag moved: the build version was taken over offset 0 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, value ) == 8, "PaddedRow's field value moved: the build version was taken over offset 8 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, flag ) == 16, "PaddedRow's field flag moved: the build version was taken over offset 16 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, id ) == 20, "PaddedRow's field id moved: the build version was taken over offset 20 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, label ) == 24, "PaddedRow's field label moved: the build version was taken over offset 24 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, slots ) == 44, "PaddedRow's field slots moved: the build version was taken over offset 44 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, teams ) == 52, "PaddedRow's field teams moved: the build version was taken over offset 52 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedRow, counter ) == 56, "PaddedRow's field counter moved: the build version was taken over offset 56 (SPEC-TABLES.md §20.3)" );
static_assert( sizeof( PaddedFrame ) == 4136, "PaddedFrame's sizeof moved: the build version was taken over 4136, so a cook of it would not be this build's file (SPEC-TABLES.md §20.3)" );
static_assert( alignof( PaddedFrame ) == 8, "PaddedFrame's alignof moved: the build version was taken over 8 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedFrame, marker ) == 0, "PaddedFrame's field marker moved: the build version was taken over offset 0 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedFrame, stamp ) == 8, "PaddedFrame's field stamp moved: the build version was taken over offset 8 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedFrame, rows ) == 16, "PaddedFrame's field rows moved: the build version was taken over offset 16 (SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PaddedFrame, blob ) == 4116, "PaddedFrame's field blob moved: the build version was taken over offset 4116 (SPEC-TABLES.md §20.3)" );

